import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const BlackjackPage = ({ socket, setBalance }) => {
  const { user } = useAuth();
  const [gameState, setGameState] = useState('waiting'); // waiting, betting, in_progress, completed
  const [currentGame, setCurrentGame] = useState(null);
  const [betAmount, setBetAmount] = useState(100);
  const [balance, setLocalBalance] = useState(user?.balance || 0);
  const [message, setMessage] = useState('');
  const [playerHand, setPlayerHand] = useState([]);
  const [dealerHand, setDealerHand] = useState([]);
  const [playerValue, setPlayerValue] = useState(0);
  const [dealerValue, setDealerValue] = useState(0);
  const [result, setResult] = useState('');

  // Update local balance when user balance changes
  useEffect(() => {
    if (user) {
      setLocalBalance(user.balance);
    }
  }, [user]);

  const startGame = async () => {
    if (betAmount > balance) {
      setMessage('Insufficient balance');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/blackjack/start`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ betAmount })
      });

      const data = await response.json();

      if (response.ok) {
        setGameState('in_progress');
        setCurrentGame(data);
        setPlayerHand(data.playerHand);
        setDealerHand(data.dealerHand);
        setPlayerValue(data.playerValue);
        setMessage('');

        // Update balance
        setLocalBalance(prev => prev - betAmount);
      } else {
        setMessage(data.message || 'Error starting game');
      }
    } catch (error) {
      console.error('Error starting blackjack game:', error);
      setMessage('Error starting game');
    }
  };

  const hit = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/blackjack/${currentGame?.gameId}/hit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      const data = await response.json();

      if (response.ok) {
        setPlayerHand(data.playerHand);
        setPlayerValue(calculateHandValue(data.playerHand));

        if (data.status === 'completed') {
          setGameState('completed');
          setResult(data.result);
          setDealerHand(data.dealerHand);
          setDealerValue(calculateHandValue(data.dealerHand));

          // Update balance based on result
          if (data.result === 'win') {
            setLocalBalance(prev => prev + (betAmount * 2));
          } else if (data.result === 'blackjack') {
            setLocalBalance(prev => prev + (betAmount * 2.5));
          } else if (data.result === 'push') {
            setLocalBalance(prev => prev + betAmount);
          }
        }
      } else {
        setMessage(data.message || 'Error hitting');
      }
    } catch (error) {
      console.error('Error hitting:', error);
      setMessage('Error hitting');
    }
  };

  const stand = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/blackjack/${currentGame?.gameId}/stand`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      const data = await response.json();

      if (response.ok) {
        setGameState('completed');
        setResult(data.result);
        setPlayerHand(data.playerHand);
        setDealerHand(data.dealerHand);
        setPlayerValue(calculateHandValue(data.playerHand));
        setDealerValue(calculateHandValue(data.dealerHand));

        // Update balance based on result
        if (data.result === 'win') {
          setLocalBalance(prev => prev + (betAmount * 2));
        } else if (data.result === 'blackjack') {
          setLocalBalance(prev => prev + (betAmount * 2.5));
        } else if (data.result === 'push') {
          setLocalBalance(prev => prev + betAmount);
        }
      } else {
        setMessage(data.message || 'Error standing');
      }
    } catch (error) {
      console.error('Error standing:', error);
      setMessage('Error standing');
    }
  };

  const calculateHandValue = (hand) => {
    if (!hand) return 0;

    let value = 0;
    let aces = 0;

    for (const card of hand) {
      if (card.rank === 'A') {
        aces++;
        value += 11;
      } else if (['J', 'Q', 'K'].includes(card.rank)) {
        value += 10;
      } else {
        value += parseInt(card.rank);
      }
    }

    // Adjust for aces if value is over 21
    while (value > 21 && aces > 0) {
      value -= 10; // Convert ace from 11 to 1
      aces--;
    }

    return value;
  };

  const resetGame = () => {
    setGameState('waiting');
    setCurrentGame(null);
    setPlayerHand([]);
    setDealerHand([]);
    setPlayerValue(0);
    setDealerValue(0);
    setResult('');
    setMessage('');
  };

  const adjustBet = (amount) => {
    const newBet = Math.max(10, Math.min(balance, betAmount + amount));
    setBetAmount(newBet);
  };

  return (
    <div className="blackjack-page">
      <div className="page-header">
        <h1>Blackjack</h1>
      </div>

      <div className="blackjack-game">
        <div className="game-info">
          <div className="balance-display">
            Balance: <span className="balance-amount">{balance.toLocaleString()}</span> AMP
          </div>
          <div className="bet-amount">
            Current Bet: <span className="bet-amount-value">{betAmount.toLocaleString()}</span> AMP
          </div>
        </div>

        {gameState === 'waiting' && (
          <div className="betting-section">
            <div className="bet-controls">
              <button className="btn btn-secondary" onClick={() => adjustBet(-100)}>
                -100
              </button>
              <button className="btn btn-secondary" onClick={() => adjustBet(-10)}>
                -10
              </button>
              <input
                type="number"
                value={betAmount}
                onChange={(e) => setBetAmount(Math.max(10, Math.min(balance, Number(e.target.value))))}
                className="bet-input"
                min="10"
                max={balance}
              />
              <button className="btn btn-secondary" onClick={() => adjustBet(10)}>
                +10
              </button>
              <button className="btn btn-secondary" onClick={() => adjustBet(100)}>
                +100
              </button>
            </div>

            <button 
              className="btn btn-primary btn-lg" 
              onClick={startGame}
              disabled={betAmount > balance}
            >
              PLAY BLACKJACK ({betAmount.toLocaleString()} AMP)
            </button>
          </div>
        )}

        {(gameState === 'in_progress' || gameState === 'completed') && (
          <div className="game-area">
            <div className="dealer-section">
              <h3>Dealer</h3>
              <div className="hand">
                {dealerHand.map((card, index) => (
                  <div key={index} className="card">
                    {card.suit === 'hidden' ? (
                      <div className="card-back">🂠</div>
                    ) : (
                      <div className="card-front">
                        <div className="card-value">{card.rank}</div>
                        <div className="card-suit">{getSuitSymbol(card.suit)}</div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
              <div className="hand-value">Value: {gameState === 'completed' ? calculateHandValue(dealerHand) : '?'}
              </div>
            </div>

            <div className="player-section">
              <h3>You</h3>
              <div className="hand">
                {playerHand.map((card, index) => (
                  <div key={index} className="card">
                    <div className="card-front">
                      <div className="card-value">{card.rank}</div>
                      <div className="card-suit">{getSuitSymbol(card.suit)}</div>
                    </div>
                  </div>
                ))}
              </div>
              <div className="hand-value">Value: {playerValue}</div>
            </div>

            {gameState === 'in_progress' && (
              <div className="game-controls">
                <button className="btn btn-primary" onClick={hit}>HIT</button>
                <button className="btn btn-secondary" onClick={stand}>STAND</button>
              </div>
            )}

            {gameState === 'completed' && (
              <div className="game-result">
                <h3>
                  {result === 'blackjack' && 'BLACKJACK! 🎉'}
                  {result === 'win' && 'YOU WIN! 🎉'}
                  {result === 'loss' && 'YOU LOSE 😞'}
                  {result === 'push' && 'PUSH (TIE) 🤝'}
                  {result === 'bust' && 'BUST! 😞'}
                </h3>
                <button className="btn btn-primary" onClick={resetGame}>PLAY AGAIN</button>
              </div>
            )}
          </div>
        )}

        {message && (
          <div className="error-message">{message}</div>
        )}
      </div>
    </div>
  );
};

const getSuitSymbol = (suit) => {
  switch(suit) {
    case 'hearts': return '♥';
    case 'diamonds': return '♦';
    case 'clubs': return '♣';
    case 'spades': return '♠';
    default: return '';
  }
};

export default BlackjackPage;
